                //---------------------------------------------------------------------
                nactiDetail(ixs_pri) {
                    if (!this.Kontrolapristupu())
                        return;
                    var that = this;
                    that.isl.EpoProdejeOdprodeje.read({
                        data: { ixs_pri: ixs_pri },
                        fragments: ["common", "detail", "minimum", "foreach"]
                    })
                        .getData()
                        .then(function (detail) {
                        var newGpc = Gordic.Eko.Utils.createBookGpc(that.gpc, detail.ixp_den);
                        var detailContent = that.navigate(["Gordic.Epo.WebClient.GEpoDetailPO", { gridRemoteControl: null, gpc: newGpc }], {
                            taskId: "actGEpoSeznamScr", data: detail
                        });
                        detailContent.on("close", function (ev, ctx) {
                            if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                                that.load();
                            }
                        });
                    });
                }
                //---------------------------------------------------------------------
                nactiSeznamBezFin(id) {
                    if (!this.Kontrolapristupu())
                        return;
                    var that = this;
                    var filtr = {};
                    if (id == 2) {
                        filtr.pole = "bez_financovani";
                        filtr.oper = "=";
                        filtr.hodnota = "";
                    }
                    else if (id == 4) {
                        filtr.pole = "bez_nasmlouvanosti";
                        filtr.oper = "=";
                        filtr.hodnota = "";
                    }
                    else if (id == 6) {
                        filtr.pole = "bez_rezervaci";
                        filtr.oper = "=";
                        filtr.hodnota = "";
                    }
                    var newGpc = Gordic.Eko.Utils.createBookGpc(this.gpc, "*rok"); //Gordic.Eko.GEkoBookVariant.year
                    var seznamContent = this.navigate(["Gordic.Epo.WebClient.GEpoSeznam", { gpc: newGpc }], {
                        taskId: "actGEpoSeznamScr", filtr: filtr
                    });
                    seznamContent.on("close", function (ev, ctx) {
                        if (ev.target === seznamContent.get(0) && ctx && ctx.isChanged) {
                            that.load();
                        }
                    });
                }
                //---------------------------------------------------------------------
                nactiSeznam(id, kniha) {
                    if (!this.Kontrolapristupu())
                        return;
                    var that = this;
                    var filtr = {};
                    switch (id) {
                        case 1:
                            filtr.pole = "s_po";
                            filtr.hodnota = "20,00"; //20,0
                            filtr.oper = "in";
                            break;
                        case 2:
                            filtr.pole = "s_po";
                            filtr.hodnota = "10";
                            filtr.oper = "=";
                            break;
                        case 3:
                            filtr.pole = "s_po";
                            filtr.hodnota = "50,80,90";
                            filtr.oper = "in";
                            break;
                        case 4:
                            filtr.pole = "c";
                            filtr.hodnota = this.limitDashBoard1.toString();
                            filtr.oper = "<";
                            break;
                        case 5:
                            filtr.pole = "c";
                            filtr.hodnota = (this.limitDashBoard1 + 1).toString() + "," + this.limitDashBoard3.toString();
                            filtr.oper = "<>";
                            break;
                        case 6:
                            filtr.pole = "c";
                            filtr.hodnota = (this.limitDashBoard3 + 1).toString() + "," + this.limitDashBoard4.toString();
                            filtr.oper = "<>";
                            break;
                        case 7:
                            filtr.pole = "c";
                            filtr.hodnota = this.limitDashBoard4.toString();
                            filtr.oper = ">";
                            break;
                    }
                    var newGpc = Gordic.Eko.Utils.createBookGpc(this.gpc, kniha);
                    var seznamContent = this.navigate(["Gordic.Epo.WebClient.GEpoSeznam", { gpc: newGpc }], {
                        taskId: "actGEpoSeznamScr", filtr: filtr
                    });
                    seznamContent.on("close", function (ev, ctx) {
                        if (ev.target === seznamContent.get(0) && ctx && ctx.isChanged) {
                            that.load();
                        }
                    });
                }
                //---------------------------------------------------------------------
                Kontrolapristupu() {
                    if (this.paramSulPri == "0") {
                        this.dialogs.warning("jres:26600630"); //RC 26600630 : Nemáte právo na prohlížení případů.
                        return false;
                    }
                    return true;
                }
