                onDetailBuilderBuild(builder) {
                    var that = this;
                    var param = {
                        parentContent: this,
                        agenda: "epo",
                        readOnly: true,
                        ktg_typ: 1,
                        soutez: this.detailDto.soutez_po == null ? null : this.detailDto.soutez_po,
                        acAgMaska: "",
                        ac_ag_enabled: false,
                        ac_enabled: false,
                        cis_real_enabled: false,
                        ixs_fun_komp_enabled: false,
                        enabledPopis: false,
                        sablona: "",
                        pripad: true,
                        xxxSoutezPrefab: Gordic.Prefabs.Select.epossop()
                    };
                    var formSetup = Gordic.Pap.WebControls.PrefabsPap.vytvorHlavParam(param);
                    Gordic.Eko.HeaderForm.setup(builder, formSetup);
                    builder.updateDefinition("menuSouvisejici", { parent: "menuWflCinnosti" }, GDbd.DefinitionKind.MenuBar);
                    this.listControls_setup({
                        // delegát, který se spustí než se provede reload contentu. Je možné zde vyvolat closing a upozornit tak uživatele, že má např. neuložené změny.
                        beforeMove: function () { return that.closing(); },
                        //funkce, která řádek z gridu přetransformuje v dto pro zavolání this.load(dto); Může vracet promise.
                        rowToDto: function (row) {
                            return that.isl.EpoProdejeOdprodeje.read({
                                data: { ixs_pri: row.currentRow.data.ixs_pri },
                                fragments: ["common", "detail"]
                            })
                                .getData()
                                .then(function (detail) {
                                return { data: detail };
                            });
                        },
                        //template pro tooltip na šipce následující
                        nextItemTemplate: "Následující: {ixs_pri} <br> {nazev}",
                        //template pro tooltip na šipce předchozí
                        prevItemTemplate: "Předchozí: {ixs_pri} <br> {nazev}"
                    });
                }
