                akceUkony() {
                    var that = this;
                    var filters = {};
                    filters.ixs_pri = this.detailDto.ixs_pri;
                    that.isl.EpospidAllDokPOService.count({ filters: filters }).get().then(function (retVal) {
                        var def0 = $.Deferred();
                        if (retVal > 20) {
                            that.dotaz("jres:26600234".replace("{0}", retVal.toString())) //RC 26600472 : Chcete při načtení seznamu provést také kontroly na Financování;a doplnění dalších rozšiřujících validačních informací žádostí?;Při počtu {0} dokumentů může operace trvat delší dobu a načítání/nenačítání platí až do opuštění seznamu!;;Provést akci?
                                .then(() => {
                                def0.resolve(true);
                            })
                                .fail(function () { def0.resolve(false); });
                        }
                        else
                            def0.resolve(true);
                        def0.then(function (doplnit) {
                            var seznamContent = that.navigate("Gordic.Epo.WebClient.GEpoSeznamDokPO", {
                                uid: "GEpoSeznamDokPO#",
                                taskId: "actGEpoSeznamScr", ixs_pri: that.detailDto.ixs_pri, doplnit: doplnit, ac_ag: that.detailDto.ac_ag, task_id: "actGEpoSeznamScr"
                            });
                            seznamContent.on("close", function (ev, ctx) {
                                if (ev.target === seznamContent.get(0) && ctx && ctx.isChanged) {
                                    that.isChanged = true;
                                    that.NactiData();
                                }
                            });
                        });
                    });
                }
