                NastavTlacitka() {
                    this.actions.schvaleniAkce.update({ enabled: this.detailDto.s_po != 10 && this.ac.schvaleni });
                    this.actions.schvaleniZrusitAkce.update({ enabled: this.detailDto.s_po == 10 && this.ac.schvaleni_zrus });
                    this.actions.ukonceniAkce.update({ enabled: this.detailDto.s_po != 50 && this.ac.ukonceni });
                    this.actions.zrusitUkonceniAkce.update({ enabled: this.detailDto.s_po == 50 && this.ac.ukonceni_zrus });
                    //    this.actions.kategorieAkce!.update({
                    //        enabled: this.detailDto.cis_zakon! > 40 ||
                    //            (this.detailDto.cis_zakon! == 40 && (this.detailDto.soutez! == "§138" || this.detailDto.soutez! == "§138 kat."))
                    //    })
                }
