                akceSchvaleni() {
                    var that = this;
                    var otazka = "jres:26600215"; //RC 26600215 : Opravdu chcete schválit případ PO?
                    var def0 = $.Deferred();
                    var def1 = $.Deferred();
                    var stru = { seznam: that.vratData(), akce: "schvaleni" };
                    this.dotaz(otazka)
                        .then(() => {
                        that.isl.PapSchvaleni.schvaleni(stru).get().then(function (retVal) {
                            if (retVal.data.hlas != "") {
                                that.dialogs.warning("jres:26600212", retVal.data.hlas); //RC 26600212 : Upozornění
                            }
                            if (retVal.data.ok) {
                                def0.resolve();
                            }
                        });
                    }, def0.reject);
                    def0.then(function () {
                        var dlg = Gordic.Pap.Dialogs.GPapSchvalitParamScr(that, { ixs_pri: that.detailDto.ixs_pri, agenda: "epo" }, Gordic.Gin.Globals.Enums.ModOtevreni.showWindow)
                            .then(function (retVal) {
                            if (retVal != null) {
                                def1.resolve(retVal);
                            }
                            else {
                                def1.reject();
                            }
                        }, def1.reject);
                    });
                    def1.then(function (retVal) {
                        var blok = [];
                        blok.push({ identifikator: that.detailDto.ixs_pri, cislo: 0, cisloDec: retVal.castka, datum: retVal.datum });
                        stru.seznam = blok;
                        that.isl.PapSchvaleni.schvaleni(stru).get().then(function (retVal) {
                            if (retVal.data.hlas != "") {
                                that.dialogs.warning("jres:26600212", retVal.data.hlas); //RC 26600274 : Upozornění
                            }
                            if (retVal.data.ok) {
                                that.isChanged = true;
                                that.NactiData();
                            }
                        });
                    });
                }
