                akceSchvaleniZrusit() {
                    var that = this;
                    var otazka = "jres:26600219"; //RC 26600219 : Opravdu chcete zrušit schválení případu PO?
                    this.dotaz(otazka)
                        .then(() => {
                        var stru = { seznam: this.vratData(), akce: "odschvaleni" };
                        that.isl.PapSchvaleni.schvaleni(stru).get().then(function (retVal) {
                            if (retVal.data.hlas != "") {
                                that.dialogs.warning("jres:26600212", retVal.data.hlas); //RC 26600276 : Upozornění
                            }
                            if (retVal.data.ok) {
                                that.isChanged = true;
                                that.NactiData();
                            }
                        });
                    }, () => {
                        //rejected promise
                    });
                }
                //---------------------------------------------------------------------
                NactiData() {
                    var that = this;
                    that.isl.EpoProdejeOdprodeje.read({
                        data: { ixs_pri: this.detailDto.ixs_pri },
                        fragments: ["common", "detail"]
                    })
                        .getData()
                        .then(function (detail) {
                        if (that.finChanged)
                            that.load({ data: that.detailDto, isChanged: that.isChanged });
                        else {
                            that.detailDto = detail;
                            that.findFields().gfield("model", "apply", that.detailDto, { setFlags: { valid: false } });
                            that.load({ data: that.detailDto });
                        }
                    });
                    //.getData()
                    //.then(function (detail) {
                    //    that.load({ data: that.detailDto, isChanged: that.isChanged })
                    //    if (that.finChanged) that.load({ data: that.detailDto, isChanged: that.isChanged })
                    //    else {
                    //        that.detailDto = detail;
                    //        that.findFields().gfield("model", "apply", that.detailDto, { setFlags: { valid: false } });
                    //        that.call("NaplnAccesButtonsDetailPO", { ixs_pri: that.detailDto.ixs_pri }).then((data) => {
                    //            that.ac = data;
                    //            that.NastavTlacitkaPoZmeneAc();
                    //        })
                    //    }
                    //})
                }
