                schvaleni() {
                    var that = this;
                    var l_hlas = this.data.parametry.nadTyp2 !== 103 /*KTGTYP_nad_main_z*/ ? "jres:26600297" : "jres:26600298"; //RC 26600298 : Schválením tohoto úkonu dojde i ke stornování položek financování a uzavření případu!;Opravdu chcete dokument schválit?
                    //RC 26600486 : Schválením tohoto úkonu dojde i ke stornování položek financování a uzavření případu!;Opravdu chcete dokument schválit?
                    this.dotaz("jres:26600232", l_hlas) //RC 26600232 : Dotaz
                        .then(() => {
                        var def = $.Deferred();
                        if (that.data.parametry.nastavCPreblok) {
                            var dlg = Gordic.Pap.Dialogs.GPapObecnyInput(this, { titulek: "jres:26600323", label: "jres:26600323", povinne: true, agenda: "epo", typ: "number", input: that.data.parametry.c_preblok.toString() } //RC 26600323 : Prostředky pro přeblokaci
                            , Gordic.Gin.Globals.Enums.ModOtevreni.showWindow)
                                .then(function (retVal) {
                                that.data.parametry.c_preblok = parseDecimal(retVal.navrat);
                                def.resolve();
                            })
                                .fail(function () {
                                that.dialogs.warning("jres:26600212", "jres:26600326"); //RC 26600326 : Nebyly nastaveny prostředky pro přeblokaci.
                                def.reject();
                            });
                        }
                        else
                            def.resolve();
                        def.then(function () {
                            that.data.parametry.akce = "schvaleniUkon";
                            that.saveData("schvaleni");
                        });
                    });
                }
