                storno() {
                    var that = this;
                    var l_hlas = "";
                    var l_param = "";
                    var l_title = "";
                    var def = $.Deferred();
                    if (this.data.pidDto.epo_stav != 90) //storno
                     {
                        that.isl.EpoDetailPO.kontrolaPredStornem({ ixp: this.data.pidDto.ixp }).get()
                            .then(function (retVal) {
                            if (retVal.hlas != "") {
                                if (retVal.hlas)
                                    l_hlas = retVal.hlas;
                            }
                            def.resolve();
                        });
                    }
                    else
                        def.resolve();
                    def.then(function () {
                        if (that.data.pidDto.epo_stav == 90) {
                            l_hlas = "jres:26600244"; //RC 26600244 : Opravdu chcete provést STORNO STORNA dokumentu?
                            l_param = "storno storna";
                            l_title = "jres:26600740"; //RC 26600740 : Důvod zrušení storna
                            that.data.parametry.akce = "stornoStornaUkon";
                        }
                        else {
                            l_hlas += that.data.parametry.nadTyp2 === 103 /*KTGTYP_nad_main_z*/ ? "jres:26600245" : "jres:26600327"; //RC 26600245 : Opravdu chcete provést STORNO dokumentu a tím i celého Převodu - odprodeje?
                            l_param = "storno";
                            l_title = "jres:26600741"; //RC 26600741 : Důvod storna
                            that.data.parametry.akce = "stornoUkon";
                        }
                        that.dotaz("jres:26600232", l_hlas) //RC 26600232 : Dotaz
                            .then(() => {
                            var dlg = Gordic.Pap.Dialogs.GPapObecnyInput(that, { titulek: "jres:26600246", label: "jres:26600247", povinne: true, agenda: "epo", typ: "string", input: "" } //RC 26600247 : Důvod
                            , Gordic.Gin.Globals.Enums.ModOtevreni.showWindow)
                                .then(function (retVal) {
                                that.data.parametry.duvodStorno = retVal.navrat;
                                that.saveData(l_param);
                            })
                                .fail(function () {
                                that.dialogs.warning("jres:26600212", "jres:26600248"); //RC 26600212 : Upozornění
                            });
                        });
                    });
                }
                //---------------------------------------------------------------------
                odschvaleni() {
                    // var l_stavNazev = this.findForms("FormZakladniUdaje").findFields("s_dgr").gfield("getValue").s_gdr_txt;
                    var l_hlas = "";
                    if (this.data.pidDto.s_po != 0 && this.data.pidDto.s_po != 20) {
                        this.dialogs.warning("jres:26600212", "jres:26600249"); //RC 26600249 : Odschválit lze dokument pouze na aktivním případu!
                    }
                    else {
                        l_hlas = "jres:26600250"; //RC 26600250 : Opravdu chcete provést odschválení dokumentu?
                    }
                    var def = $.Deferred();
                    if (l_hlas != "") {
                        this.dotaz("jres:26600232", l_hlas) //RC 26600232 : Dotaz
                            .then(() => {
                            this.data.parametry.odschval = true;
                            this.data.parametry.saveStav = this.data.pidDto.s_po;
                            this.saveData("odSchvaleni");
                            this.data.parametry.akce = "odschvaleniUkon";
                        });
                    }
                }
