                    this.actions.podaniAkce.update({ enabled: this.data.prava.podani && this.ac_ag != null && !this.modPU });
                    this.actions.evidenceAkce.update({ enabled: this.data.prava.evidence });
                    this.actions.schvaleniAkce.update({ enabled: this.data.prava.schvaleni && !this.modPU });
                    //this.actions.schProstAkce!.update({ enabled: this.data.prava!.up_c_real! })
                    this.actions.odSchvaleniAkce.update({ enabled: this.data.prava.odschvaleni && !this.modPU });
                    this.actions.stornoAkce.update({ enabled: this.data.prava.storno && !this.modPU });
                    this.actions.financovaniAkce.update({ enabled: this.data.prava.financovani && !this.modPU });
                    this.actions.dotSubjAkce.update({ enabled: this.data.prava.okr /*!!!!!!!!!!!!!!!*/ });
                    //this.actions.okrAkce!.update({ enabled: this.data.prava!.okr! })
                    //this.actions.pzaDTAkce!.update({ enabled: this.data.prava!.pza! })
                    //this.actions.plneniAkce!.update({ enabled: this.data.prava!.ovc! })
                    //this.actions.varPoleAkce!.update({ enabled: this.data.prava!.vlastnosti! })
                    this.actions.elPrilohyAkce.update({ enabled: this.data.prava.elpri && !this.modPU });
                    this.actions.actTiskDetailDok.update({ enabled: this.data.prava.tisk && !this.modPU });
                    this.actions.eleobrazAkce.update({ enabled: this.data.prava.eleobraz && !this.modPU });
                    this.actions.predaniAkce.update({ enabled: this.data.prava.predani && !this.modPU });
                    this.actions.prevzetiAkce.update({ enabled: this.data.prava.prevzeti && !this.modPU });
                    this.actions.prideleniAkce.update({ enabled: this.data.prava.prideleni && !this.modPU });
                    this.actions.vlozspisnetAkce.update({ enabled: this.data.prava.vlozspisnet && !this.modPU });
                    this.actions.vlozspisZadAkce.update({ enabled: this.data.prava.vlozspisnet && !this.modPU });
                    this.actions.schvalprocAkce.update({ enabled: this.data.prava.schvalproc && !this.modPU });
                    this.actions.vraceniDokladuDoWflAkce.update({ enabled: this.data.prava.vracenidokladudowfl && !this.modPU });
