                //---------------------------------------------------------------------
                nactiDetail() {
                    var l_mod = this.modOkna;
                    if (this.modPU)
                        l_mod += "PU";
                    this.load({ isChanged: true, dotazPF: this.dotazPF, modOkna: l_mod });
                }
                //---------------------------------------------------------------------
                closing() {
                    var that = this;
                    if (that.prosloOCR && !this.uzavritBezpodminecne && this.detailChanged()) { //detail byl změněn, zobrazíme dotaz na opuštění
                        return Gordic.Eko.Detail.messageBoxUnsavedData(that)
                            .createDialogPromise(GDlg.mbbYes.id)
                            .then(function () {
                            // "yes" -> zavolat a počkat pouze na uložení (bez reloadu detailu), vrátit isChanged
                            return that.saveData("evidence", false)
                                .then(function () {
                                that.element.off('.epo');
                                return { isChanged: that.isChanged };
                            })
                                .fail(function () { return $.Deferred().reject().promise(); });
                        }, function (retVal) {
                            if (retVal.returnValue === "no") { // pouze na "no" chceme zavřít (musíme vrátit resolved) a pro jistotu pošleme isChanged, ale nebudeme ukládat
                                that.element.off('.epo');
                                return $.Deferred().resolve({ isChanged: that.isChanged }).promise();
                            }
                            else //cancel
                                return $.Deferred().reject().promise();
                            //na vše ostatní nechat reject -> nezavírat
                        });
                    }
                    //pokud nebyl detail změněn, pro jistotu vrátíme isChanged, odregistrujeme eventy a umožníme uzavření (resolve)
                    return $.Deferred().resolve({ isChanged: that.isChanged, ixp: that.data.pidDto.ixp }).promise().always(function () {
                        that.element.off('.epo');
                    });
                }
                //---------------------------------------------------------------------
                detailChanged() {
                    var zmena = false;
                    var zmena = this.findForms(Gordic.Eko.HeaderForm.Name).gform("hasChanged") ||
                        this.findForms("FormZakladniUdaje").gform("hasChanged") ||
                        this.findForms("FormBlizsiUrceni").gform("hasChanged") ||
                        this.findForms("FormKomentar").gform("hasChanged");
                    if (!zmena) {
                        switch (this.data.parametry.nadTyp1) {
                            case 1: /*KTGTYP_nad_main*/
                                zmena = this.findForms("Form04").gform("hasChanged");
                                break;
                            case 2:
                                zmena = this.findForms("Form03").gform("hasChanged");
                                break;
                            case 3: /*KTGTYP_nad_sou*/
                                zmena = this.findForms("Form03").gform("hasChanged") || this.findForms("Form04").gform("hasChanged");
                                if (this.data.parametry.nadTyp2 == 108 /*KTGTYP_nad_sou_n*/)
                                    zmena = this.findForms("Form11").gform("hasChanged");
                                else
                                    zmena = this.findForms("FormSoutez").gform("hasChanged");
                                break;
                            case 7: /*KTGTYP_nad_opr*/
                                zmena = this.findForms("FormOpravFin").gform("hasChanged") || this.findForms("FormOpravEsu").gform("hasChanged");
                                break;
                            case 4: /*KTGTYP_nad_esu*/
                                if (this.data.pidDto?.ktg_typ == 2222) {
                                    zmena = this.zmenaHr();
                                }
                                else {
                                    zmena = this.findForms("FormSubjekt").gform("hasChanged");
                                }
                                break;
                            case 5: /*KTGTYP_nad_esu_hr*/
                                zmena = this.zmenaHr();
                                break;
                        }
                    }
                    return zmena;
                }
