                function NaplnDisable(vl_soutez, pole_s, pole_p, nadTyp02) {
                    var disable = [false, false, false, false, false];
                    if (vl_soutez == "")
                        disable = [true, true, true, true, true];
                    else {
                        if (vl_soutez == "OVS (M01)")
                            disable = [false, true, true, false, false];
                        else {
                            if (nadTyp02 == 101 /*KTGTYP_nad_main_s*/ || nadTyp02 == 102 /*KTGTYP_nad_main_o*/)
                                disable = [false, true, true, true, false];
                            else
                                disable = [true, true, true, true, true];
                        }
                        if (pole_s != null && pole_p != null) {
                            for (var i = 0, I = pole_s.length; i < I; i++) {
                                if (pole_p[i] == null)
                                    disable[i] = true;
                                if (pole_s[i] != null)
                                    disable[i] = true;
                            }
                        }
                    }
                    var l_ena = {
                        dat_zad_p_04: !disable[0],
                        dat_kos_p_04: !disable[1],
                        dat_uza_p_04: !disable[2],
                        dat_sml_p_04: !disable[3],
                        dat_real_p_04: !disable[4],
                    };
                    return l_ena;
                }
                PrefabsEpo.NaplnDisable = NaplnDisable;
