                function PorovnejDatum(date1, date2) {
                    var navrat = "";
                    if (date1.getFullYear() == date2.getFullYear()) {
                        if (date1.getMonth() == date2.getMonth()) {
                            if (date1.getDate() == date2.getDate())
                                navrat = "=";
                            else if (date1.getDate() > date2.getDate())
                                navrat = ">";
                            else
                                navrat = "<";
                        }
                        else {
                            if (date1.getMonth() > date2.getMonth())
                                navrat = ">";
                            else
                                navrat = "<";
                        }
                    }
                    else {
                        if (date1.getFullYear() > date2.getFullYear())
                            navrat = ">";
                        else
                            navrat = "<";
                    }
                    return navrat;
                }
