                //#endregion 
                //---------------------------------------------------------------------
                nastavEnableTlacitek() {
                    if (this.grid.hasClass('ggrid')) {
                        var row = this.grid.ggrid("getSelection")[0];
                        if (row)
                            this.actions.actPodani.enabled((row.vlastnik || this.paramGvycza == 1) && this.ap.podani);
                    }
                    else
                        this.actions.actPodani.enabled(false);
                }
                //---------------------------------------------------------------------
                nactiDetail() {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    that.isl.EpoProdejeOdprodeje.read({
                        data: { ixs_pri: row.ixs_pri },
                        fragments: ["common", "detail"]
                    })
                        .getData()
                        .then(function (detail) {
                        var newGpc = Gordic.Eko.Utils.createBookGpc(that.gpc, row.ixp_den);
                        var detailContent = that.navigate(["Gordic.Epo.WebClient.GEpoDetailPO", {
                                gridRemoteControl: new Gordic.Components.GridRC(that.grid), gpc: newGpc
                            }], {
                            taskId: "actGEpoSeznamScr",
                            uid: "GEpoDetailPO#",
                            data: detail
                        });
                        detailContent.on("close", function (ev, ctx) {
                            if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                                var focusFunc = function () {
                                    if (that.grid.hasClass('ggrid')) {
                                        that.grid.ggrid('focus'); // nastavení focusu na grid
                                        that.view.off('change.focus', focusFunc); // odvázání události z ISL view
                                    }
                                };
                                that.view.on('change.focus', focusFunc);
                                that.obnovSeznam();
                            }
                            else
                                detailContent.one('closed', function () { if (that.grid.hasClass('ggrid'))
                                    that.grid.ggrid('focus'); });
                        });
                    }).done(() => { });
                }
                //---------------------------------------------------------------------
                nastavTlacitka() {
                    var isBookSelected = Gordic.Eko.Utils.getEkoBookVariant(this) === 1 /* Eko.Interface.GEkoBookVariant.One */ ? true : false; // pokud je toto false, jsou vybrané všechny knihy/knihy za rok/není kniha
                    var enabled = this.view.getCount("filter") > 0;
                    this.actions.actNovyPO.enabled(this.ap.podani && isBookSelected);
                    this.actions.actDetailPO.enabled(enabled);
                    this.actions.actUkony.enabled(enabled);
                    this.actions.actPodani.enabled(enabled && this.ap.podani);
                    this.actions.actNavrhy.enabled(enabled && this.ap.generuj_sml);
                    this.actions.actUzavreni.enabled(enabled);
                    //this.actions.actUzavreniZrusit!.enabled(enabled);
                    this.actions.actUkonceni.enabled(enabled);
                    this.actions.actUkonceniZrusit.enabled(enabled);
                    this.actions.actUvolneni.enabled(enabled && this.ap.uvolneni);
                    this.actions.actPreevidence.enabled(enabled && this.ap.preevidence);
                    this.actions.actPredani.enabled(enabled && this.ap.predani);
                    this.actions.actPrevzeti.enabled(enabled && this.ap.prevzeti);
                    this.actions.actPrideleni.enabled(enabled && this.ap.prideleni);
                    this.actions.actKlicovaSlova.enabled(enabled);
                    this.actions.actTisky.enabled(enabled);
                }
                //---------------------------------------------------------------------
