                            akce: "uvolneni", // chvaleni, odschvaleni, ukonceni, odukonceni
                            description: "jres:26600554", // popis akce //RC 26600554 : Uvolnění případu
                            nazevAkce: "jres:26600553", // název výkonné akce  //RC 26600553 : Uvolnění
