                //---------------------------------------------------------------------
                getOpenDetailDelegate() {
                    var that = this;
                    return (cnt, grid, row) => {
                        let newGpc = (row != null ? Gordic.Eko.Utils.createBookGpc(cnt.gpc, row.ixp_den) : cnt.gpc);
                        let gridRC = new Gordic.Components.GridRC(grid); //pohyb po gridu
                        that.isl.EpoProdejeOdprodeje.read({
                            data: { ixs_pri: row.identifikator },
                            fragments: ["common", "detail", "minimum", "foreach"]
                        })
                            .getData()
                            .then(function (detail) {
                            var detailContent = cnt.navigate(["Gordic.Epo.WebClient.GEpoDetailPO", {
                                    gridRemoteControl: gridRC
                                }], {
                                taskId: "actGEpoSeznamScr", data: detail,
                                uid: "GEpoDetailPO#"
                            });
                        });
                    };
                }
                //---------------------------------------------------------------------
                preevidence() {
                    var that = this;
                    var otazka = "jres:26600569"; //RC 26600569 : Opravdu chcete provést přeevidenci označených případů PO?
                    this.dotaz(otazka)
                        .then(() => {
                        Gordic.Pap.WebControls.PapHromadneOperace.Preevidence({
                            parentContent: that,
                            data: that.vratData(),
                            completeDelegate: (view) => {
                                that.obnovSeznam();
                            },
                            allDok: false,
                            preevidenceData: that.preevidenceData,
                            akce: null,
                            nazev: null,
                            openDetailDelegate: that.getOpenDetailDelegate()
                        });
                    });
                }
                //---------------------------------------------------------------------
                podani(ele) {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    Gordic.Epo.Dialogs.GEpoPodani(this, {
                        genIxp: this.genIxp, ixp: null, ktg_typ: -5, ele: false, ixs_krk: null, modOkna: "new",
                        ixs_pri: row !== undefined ? row.ixs_pri : null, allDok: true, ac_ag: row !== undefined ? row.ac_ag : null, soutez: row !== undefined ? row.soutez_po : null, ixs_esu: "", por_cis_nab: -1, novyPO: false
                    })
                        .then(function (retval) {
                        var detailContent = that.navigate("Gordic.Epo.WebClient.GEpoDetail", {
                            taskId: "actGEpoSeznamScr",
                            uid: "GEpoDetail#",
                            ixp: retval.ixp, ktg_typ: retval.ktg_typ, ele: false, ixs_krk: retval.ixs_krk, modOkna: "newEdit", ixs_pri: retval.ixs_pri, podaniOut: false, allDok: true, ac_ag: null, soutez: retval.soutez, ixs_esu: ""
                        });
                        detailContent.on("close", function (ev, ctx) {
                            if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                                var focusFunc = function () {
                                    if (that.grid.hasClass('ggrid')) {
                                        that.grid.ggrid('focus'); // nastavení focusu na grid
                                        that.view.off('change.focus', focusFunc); // odvázání události z ISL view
                                    }
                                };
                                that.view.on('change.focus', focusFunc);
                                that.isChanged = true;
                                that.obnovSeznam();
                            }
                            else
                                detailContent.one('closed', function () { if (that.grid.hasClass('ggrid'))
                                    that.grid.ggrid('focus'); });
                        });
                    });
                }
                //---------------------------------------------------------------------
                showComparison(rows) {
                    var that = this;
                    if (rows.length > 0) {
                        var dataRows = rows.map(function (item, idx) { return item.data; }); // převod z grid metadata-view do pole dto
                        if (this.isComparisonInited) {
                            this.addToComparison(dataRows);
                        }
                        else {
                            this.isComparisonInited = true;
                            this.comparisonCnt.empty();
                            this.comparator = $('<div class="js-comparator">').appendTo(this.comparisonCnt).gcomparator({
                                items: dataRows,
                                columns: that.grid.ggrid("option", "columns"),
                                itemTemplate: "{ixs_pri}",
                                itemchange: function (ev, ctx) {
                                    that.comparisonBadge.value = ctx.count.toString();
                                    that.comparisonBadge.update();
                                },
                                selection: function (ev, ctx) {
                                    that.grid.ggrid("activeRow", ctx.item);
                                }
                            });
                        }
                        for (var row in rows) {
                            rows[row].checked = false;
                        }
                        this.grid.ggrid("refresh");
                    }
                }
                //---------------------------------------------------------------------
                addToComparison(rows) {
                    this.comparator.gcomparator("addItems", rows);
                }
