                //---------------------------------------------------------------------
                akceDetail() {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    var l_zaznam = {};
                    l_zaznam.Ixp = row.ixp;
                    l_zaznam.IsFavorite = !(row.priznak == 20); // 20 = příloha
                    var l_file = {};
                    l_file.Ixb = row.ixb;
                    l_file.Type = row.typ_soub;
                    l_file.Name = row.soubor;
                    l_zaznam.File = l_file;
                    var detail = Gordic.Wfl.AttachmentUtils.OpenAttachment(this, l_zaznam, false /*jestli umožnit uložení*/, false /*uzamknout … default je false*/)
                        .always(() => { if (that.grid.hasClass('ggrid'))
                        that.grid.ggrid('focus'); });
                }
                //---------------------------------------------------------------------
                showComparison(rows) {
                    var that = this;
                    if (rows.length > 0) {
                        var dataRows = rows.map(function (item, idx) { return item.data; }); // převod z grid metadata-view do pole dto
                        if (this.isComparisonInited) {
                            this.addToComparison(dataRows);
                        }
                        else {
                            this.isComparisonInited = true;
                            this.comparisonCnt.empty();
                            this.comparator = $('<div class="js-comparator">').appendTo(this.comparisonCnt).gcomparator({
                                items: dataRows,
                                columns: that.grid.ggrid("option", "columns"),
                                itemTemplate: "{ixp}",
                                itemchange: function (ev, ctx) {
                                    that.comparisonBadge.value = ctx.count.toString();
                                    that.comparisonBadge.update();
                                },
                                selection: function (ev, ctx) {
                                    that.grid.ggrid("activeRow", ctx.item);
                                }
                            });
                        }
                        for (var row in rows) {
                            rows[row].checked = false;
                        }
                        this.grid.ggrid("refresh");
                    }
                }
                //---------------------------------------------------------------------
                addToComparison(rows) {
                    this.comparator.gcomparator("addItems", rows);
                }
