                //---------------------------------------------------------------------
                nastavTlacitka() {
                    var that = this;
                    var enabled = false;
                    enabled = this.view.getCount("filter") > 0;
                    var def0 = $.Deferred();
                    if (enabled) {
                        var row = this.grid.ggrid("activeRow");
                        if (row && row.ixs_pri != that.ixsPriSave) {
                            that.call("NastavPrava", { ixs_pri: row.ixs_pri }).then(function (data) {
                                def0.resolve(data);
                            });
                        }
                        else
                            def0.reject();
                    }
                    else
                        def0.reject();
                    def0.then(function (ap) {
                        that.actions.actPodani.enabled(enabled && ap.podani);
                        that.actions.actPodaniEl.enabled(enabled && ap.podaniel);
                        that.actions.actDetail.enabled(enabled && ap.detail);
                        that.actions.actSchvalitPis.enabled(enabled && ap.schvalit);
                        that.actions.actOdSchvalitPis.enabled(enabled && ap.schvalit);
                        //this.actions.actPredvyhodn!.enabled(enabled && this.ap.predvyhodnoceni!);
                        //this.actions.actNavrhy!.enabled(enabled && this.ap.predvyhodnoceni!);
                        //this.actions.actLokality!.enabled(enabled /*nevím*/);
                        that.actions.actPVPP.enabled(enabled && ap.predani_pis);
                        that.actions.actPAllVPP.enabled(enabled && ap.predani_vlapis);
                        that.actions.actPAllPP.enabled(enabled && ap.predani);
                        that.actions.actPreevidence.enabled(enabled && ap.preevid_esu);
                        //           this.actions.actZmenaSubjDok!.enabled(enabled && this.ap.zamen_esu!);
                        that.actions.actUkonceni.enabled(enabled && ap.ukonceni);
                        that.actions.actZrusitUkonceni.enabled(enabled && ap.ukonceni_zrus);
                        that.actions.actStornoPis.enabled(enabled && ap.stornopis);
                        that.actions.actStornoPisZrus.enabled(enabled && ap.stornopis);
                        //this.actions.actGenDok!.enabled(enabled /*nevím*/);
                        that.actions.actTisky.enabled(enabled);
                    });
                }
