                //---------------------------------------------------------------------
                obnovSeznam() {
                    if (this.refreshData)
                        this.view.requestData();
                }
                //---------------------------------------------------------------------
                akcePodani(ele) {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    Gordic.Epo.Dialogs.GEpoPodani(this, { genIxp: this.genIxp, ixp: null, ktg_typ: row.ktg_typ, ele: false, ixs_krk: null, modOkna: "new", ixs_pri: row.ixs_pri, allDok: false, ac_ag: row.ac_ag, soutez: row.soutez_po, ixs_esu: that.ixs_esu, por_cis_nab: -1, novyPO: false })
                        .then(function (retval) {
                        var detailContent = that.navigate("Gordic.Epo.WebClient.GEpoDetail", {
                            //taskId: "actGEpoSeznamScr",
                            uid: "GEpoDetail#",
                            ixp: retval.ixp, ktg_typ: retval.ktg_typ, ele: false, ixs_krk: retval.ixs_krk, modOkna: "newEdit", ixs_pri: retval.ixs_pri, podaniOut: false, allDok: true, ac_ag: null, soutez: retval.soutez, ixs_esu: that.ixs_esu
                        });
                        detailContent.on("close", function (ev, ctx) {
                            if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                                var focusFunc = function () {
                                    if (that.grid.hasClass('ggrid')) {
                                        that.grid.ggrid('focus'); // nastavení focusu na grid
                                        that.view.off('change.focus', focusFunc); // odvázání události z ISL view
                                    }
                                };
                                that.view.on('change.focus', focusFunc);
                                that.view.requestData();
                            }
                            else
                                detailContent.one('closed', function () { if (that.grid.hasClass('ggrid'))
                                    that.grid.ggrid('focus'); });
                        });
                    });
                }
                //---------------------------------------------------------------------
                akceDetail() {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    var detailContent = this.navigate(["Gordic.Epo.WebClient.GEpoDetail", {
                            gridRemoteControl: new Gordic.Components.GridRC(that.grid)
                        }], {
                        //taskId: "actGEpoSeznamScr",
                        uid: "GEpoDetail#",
                        ixs_pri: row.ixs_pri, modOkna: "edit", ele: false, ixp: row.ixp, ixs_krk: row.ixs_krk, ktg_typ: row.ktg_typ, ac_ag: row.ac_ag, allDok: false, soutez: row.soutez_po, ixs_esu: ""
                    }); //zobrazeni dalsiho detailu - stejne okno
                    detailContent.on("close", function (ev, ctx) {
                        if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                            that.isChanged = true;
                            var focusFunc = function () {
                                if (that.grid.hasClass('ggrid')) {
                                    that.grid.ggrid('focus'); // nastavení focusu na grid
                                    that.view.off('change.focus', focusFunc); // odvázání události z ISL view
                                }
                            };
                            that.view.on('change.focus', focusFunc);
                            that.view.requestData();
                        }
                        else
                            detailContent.one('closed', function () { if (that.grid.hasClass('ggrid'))
                                that.grid.ggrid('focus'); });
                    });
                }
                //---------------------------------------------------------------------
                akceSchvalitPis(storno) {
                    var that = this;
                    var blok = this.grid.ggrid("getSelection");
                    this.dotaz("jres:26600535", storno ? "jres:26600533" : "jres:26600534") //RC 26600533 : Opravdu chcete hromadné odschválení označených dokumentů?
                        .then(function () {
                        Gordic.Epo.WebClient.EpoPrefabsAll.SchvalitPis({
                            parentContent: that,
                            data: that.grid.ggrid("getSelection"),
                            zrusit: storno,
                            completeDelegate: (view) => {
                                that.view.requestData();
                            },
                            allDok: false
                        });
                    });
                }
                //---------------------------------------------------------------------
                dotaz(titulek, otazka) {
                    return this.dialogs.confirm(titulek, otazka).createDialogPromise("yes");
                }
                //---------------------------------------------------------------------
                akceStorno(storno) {
                    var that = this;
                    var l_hlas = "";
                    var l_param = "";
                    if (storno) {
                        l_hlas = "jres:26600536"; //RC 26600536 : Opravdu chcete provést STORNO STORNA dokumentu?
                    }
                    else {
                        l_hlas = "jres:26600537"; //RC 26600537 : Opravdu chcete provést STORNO dokumentu?
                    }
                    this.dotaz("jres:26600538", l_hlas) //RC 26600538 : Dotaz
                        .then(() => {
                        Gordic.Epo.WebClient.EpoPrefabsAll.StornoPis({
                            parentContent: that,
                            data: that.grid.ggrid("getSelection"),
                            zrusit: storno,
                            completeDelegate: (view) => {
                                view.requestData();
                            },
                            allDok: false
                        });
                    });
                }
                //---------------------------------------------------------------------
                akceUkonceni(storno) {
                    var that = this;
                    var l_text = "jres:26600539"; //RC 26600539 : ukončení
                    if (storno)
                        l_text = "jres:26600540"; //RC 26600540 : zrušení ukončení
                    this.dotaz("jres:26600538", "jres:26600541".replace("{0}", l_text)) //RC 26600541 : Opravdu chcete provést {0} vybraných dokumentů?
                        .then(() => {
                        Gordic.Epo.WebClient.EpoPrefabsAll.UkonceniPis({
                            parentContent: that,
                            data: that.grid.ggrid("getSelection"),
                            zrusit: storno,
                            completeDelegate: (view) => {
                                view.requestData();
                            },
                            allDok: false
                        });
                    });
                }
